/**
 * 统计区组内已批准揭盲的数量；封存前置校验使用：区组已揭盲则禁止封存。
 */
public int countApprovedByBlock(String experimentId, int blockNo) {
    Integer count = jdbc.queryForObject(
            "SELECT COUNT(*) FROM unblind_request u "
                    + "JOIN allocation a ON a.id = u.allocation_id "
                    + "WHERE a.experiment_id = ? AND a.block_no = ? AND u.status = 'APPROVED'",
            Integer.class, experimentId, blockNo);
    return count == null ? 0 : count;
}

